// Known-answer vectors for transit (transit ADR invariant 1). Construction,
// frozen once and never regenerated by re-running the code under test (the
// derivation and MAC were cross-checked against an independent HKDF/HMAC
// implementation when frozen):
// material = bytes 0x00..0x1f; binding org_1/prj_1/env_1, key tk_1, version 3;
// nonce = 24×0xA5; plaintext "golden transit"; context "ctx"; signed and MACed
// message "golden".
const (
	transitGoldenAEADKeyHex   = "74ecebe391dab624bbb4619b017d978b2f0e54db45d158fb94ae3f8fe9c55bff"
	transitGoldenHMACKeyHex   = "7c106bdc633c34bed6d711df3f38aad3b149f0fc1f37f7aa57e9181ca122260e"
	transitGoldenPublicKeyHex = "9701d2c503ad739844915e9b47b6e17f4c0f95b8e121841e6c74b9e767af2d1d"
	transitGoldenRecordHex    = "01080100000004746b5f310000000300000018a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5f8e6985809daa893d199eb689d4d40b9cd97e8ecceb46670fa3b133fdc51"
	transitGoldenSignatureHex = "63fb4177133385b6134502e38300858773a1cea5addbe4b3f702b7619470c889bccb79355a6b3c4d47dfdb83639e9d8d9c7f93e0781164aa9e33f4927b7e4c09"
	transitGoldenMACHex       = "defddfc738e4e2b34d75fb1b5f674a532d454208022b72ee1dbfc307141e8d19"
)

func goldenMaterial() []byte {
	m := make([]byte, TransitMaterialSize)
	for i := range m {
		m[i] = byte(i)
	}
	return m
}

func goldenBinding(a TransitAlgorithm) TransitBinding {
	return TransitBinding{Algorithm: a, OrgID: "org_1", ProjectID: "prj_1", EnvID: "env_1", KeyID: "tk_1", Version: 3}
}

func mustTransitKey(t *testing.T, a TransitAlgorithm) *TransitKey {
	t.Helper()
	k, err := OpenTransitKey(goldenMaterial(), goldenBinding(a))
	if err != nil {
		t.Fatal(err)
	}
	return k
}

func mustHex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatalf("bad frozen vector %q: %v", s, err)
	}
	return b
}

func TestTransitKnownAnswerDerivation(t *testing.T) {
	aead := mustTransitKey(t, TransitXChaCha20Poly1305)
	if got := hex.EncodeToString(aead.key); got != transitGoldenAEADKeyHex {
		t.Errorf("xchacha derived key = %s, want %s: the derivation changed", got, transitGoldenAEADKeyHex)
	}
	mac := mustTransitKey(t, TransitHMACSHA256)
	if got := hex.EncodeToString(mac.key); got != transitGoldenHMACKeyHex {
		t.Errorf("hmac derived key = %s, want %s: the derivation changed", got, transitGoldenHMACKeyHex)
	}
	if bytes.Equal(aead.key, mac.key) {
		t.Error("two algorithms over one material derived the same key: the algorithm is not bound")
	}
	sig := mustTransitKey(t, TransitEd25519)
	pub, err := sig.PublicKey()
	if err != nil {
		t.Fatal(err)
	}
	if got := hex.EncodeToString(pub); got != transitGoldenPublicKeyHex {
		t.Errorf("ed25519 public key = %s, want %s: the derivation changed", got, transitGoldenPublicKeyHex)
	}
}

func TestTransitKnownAnswerRecordOpens(t *testing.T) {
	k := mustTransitKey(t, TransitXChaCha20Poly1305)
	pt, err := k.Decrypt(mustHex(t, transitGoldenRecordHex), []byte("ctx"))
	if err != nil {
		t.Fatalf("golden transit record failed to open, the wire format changed: %v", err)
	}
	if string(pt) != "golden transit" {
		t.Fatalf("plaintext = %q", pt)
	}
	// And sealing with the frozen nonce reproduces it byte for byte.
	k.rnd = bytes.NewReader(bytes.Repeat([]byte{0xA5}, 24))
	record, err := k.Encrypt([]byte("golden transit"), []byte("ctx"))
	if err != nil {
		t.Fatal(err)
	}
	if got := hex.EncodeToString(record); got != transitGoldenRecordHex {
		t.Fatalf("record = %s, want %s", got, transitGoldenRecordHex)
	}
}

func TestTransitKnownAnswerSignatureAndMAC(t *testing.T) {
	sig, err := mustTransitKey(t, TransitEd25519).Sign([]byte("golden"))
	if err != nil {
		t.Fatal(err)
	}
	if got := hex.EncodeToString(sig); got != transitGoldenSignatureHex {
		t.Errorf("signature = %s, want %s", got, transitGoldenSignatureHex)
	}
	if !VerifyTransitSignature(TransitEd25519, mustHex(t, transitGoldenPublicKeyHex), []byte("golden"), mustHex(t, transitGoldenSignatureHex)) {
		t.Error("frozen signature does not verify")
	}
	mac, err := mustTransitKey(t, TransitHMACSHA256).MAC([]byte("golden"))
	if err != nil {
		t.Fatal(err)
	}
	if got := hex.EncodeToString(mac); got != transitGoldenMACHex {
		t.Errorf("mac = %s, want %s", got, transitGoldenMACHex)
	}
}

func TestTransitKindBytePinned(t *testing.T) {
	if byte(TransitAAD{}.kind()) != 8 {
		t.Fatal("transit kind byte must be 8: kind bytes are persisted format")
	}
}

// Transplant (transit ADR invariant 2): a ciphertext opens under exactly one
// key, version, environment, project, org and context.
func TestTransitTransplantRefused(t *testing.T) {
	base := goldenBinding(TransitXChaCha20Poly1305)
	k, err := OpenTransitKey(goldenMaterial(), base)
	if err != nil {
		t.Fatal(err)
	}
	record, err := k.Encrypt([]byte("secret"), []byte("ctx"))
	if err != nil {
		t.Fatal(err)
	}
	mutate := map[string]func(b *TransitBinding){
		"org":     func(b *TransitBinding) { b.OrgID = "org_2" },
		"project": func(b *TransitBinding) { b.ProjectID = "prj_2" },
		"env":     func(b *TransitBinding) { b.EnvID = "env_2" },
		"key":     func(b *TransitBinding) { b.KeyID = "tk_2" },
		"version": func(b *TransitBinding) { b.Version = 4 },
	}
	for name, m := range mutate {
		b := base
		m(&b)
		other, err := OpenTransitKey(goldenMaterial(), b)
		if err != nil {
			t.Fatal(err)
		}
		if _, err := other.Decrypt(record, []byte("ctx")); !errors.Is(err, ErrDecrypt) {
			t.Errorf("%s transplant opened: %v", name, err)
		}
	}
	if _, err := k.Decrypt(record, []byte("other")); !errors.Is(err, ErrDecrypt) {
		t.Error("wrong context opened")
	}
	if _, err := k.Decrypt(record, nil); !errors.Is(err, ErrDecrypt) {
		t.Error("missing context opened")
	}
	// A non-transit envelope kind under the same key bytes never opens as
	// transit, and a header edit fails authentication.
	tampered := bytes.Clone(record)
	tampered[1] = byte(KindProjectField)
	if _, err := k.Decrypt(tampered, []byte("ctx")); !errors.Is(err, ErrDecrypt) {
		t.Error("kind-byte tamper opened")
	}
}

func TestTransitWrongAlgorithmRefused(t *testing.T) {
	sig := mustTransitKey(t, TransitEd25519)
	if _, err := sig.Encrypt([]byte("x"), nil); err == nil {
		t.Error("signing key encrypted")
	}
	if _, err := sig.MAC([]byte("x")); err == nil {
		t.Error("signing key MACed")
	}
	aead := mustTransitKey(t, TransitXChaCha20Poly1305)
	if _, err := aead.Sign([]byte("x")); err == nil {
		t.Error("encryption key signed")
	}
	if _, err := aead.PublicKey(); err == nil {
		t.Error("encryption key exposed a public key")
	}
	if _, err := mustTransitKey(t, TransitHMACSHA256).Encrypt([]byte("x"), nil); err == nil {
		t.Error("hmac key encrypted")
	}
}

func TestTransitBoundsEnforced(t *testing.T) {
	k := mustTransitKey(t, TransitXChaCha20Poly1305)
	if _, err := k.Encrypt(make([]byte, MaxTransitPlaintextBytes+1), nil); err == nil {
		t.Error("oversized plaintext sealed")
	}
	if _, err := k.Encrypt(nil, make([]byte, MaxTransitContextBytes+1)); err == nil {
		t.Error("oversized context sealed")
	}
	if _, err := mustTransitKey(t, TransitEd25519).Sign(make([]byte, MaxTransitPlaintextBytes+1)); err == nil {
		t.Error("oversized message signed")
	}
	for _, bits := range []int{0, 8, 64, 192, 1024, 257} {
		if _, err := NewTransitDataKey(bits); err == nil {
			t.Errorf("data key of %d bits accepted", bits)
		}
	}
	for _, bits := range []int{128, 256, 512} {
		dk, err := NewTransitDataKey(bits)
		if err != nil || len(dk) != bits/8 {
			t.Errorf("data key of %d bits: len %d err %v", bits, len(dk), err)
		}
	}
}

func TestTransitBindingValidated(t *testing.T) {
	b := goldenBinding(TransitXChaCha20Poly1305)
	b.Version = 0
	if _, err := OpenTransitKey(goldenMaterial(), b); err == nil {
		t.Error("version 0 accepted")
	}
	b = goldenBinding("aes-ecb")
	if _, err := OpenTransitKey(goldenMaterial(), b); err == nil {
		t.Error("unknown algorithm accepted")
	}
	if _, err := OpenTransitKey(make([]byte, 16), goldenBinding(TransitHMACSHA256)); err == nil {
		t.Error("short material accepted")
	}
}

func TestTransitValueRoundTripAndRefusals(t *testing.T) {
	k := mustTransitKey(t, TransitXChaCha20Poly1305)
	record, err := k.Encrypt([]byte("hello"), nil)
	if err != nil {
		t.Fatal(err)
	}
	wire := FormatTransitValue(3, record)
	if !strings.HasPrefix(wire, "hikyo:v3:") {
		t.Fatalf("wire = %s", wire)
	}
	v, got, err := ParseTransitCiphertext(wire, "tk_1")
	if err != nil || v != 3 || !bytes.Equal(got, record) {
		t.Fatalf("round trip: v=%d err=%v", v, err)
	}
	// The textual version must equal the authenticated header version.
	if _, _, err := ParseTransitCiphertext(FormatTransitValue(4, record), "tk_1"); err == nil {
		t.Error("prefix/header version mismatch accepted")
	}
	if _, _, err := ParseTransitCiphertext(wire, "tk_2"); err == nil {
		t.Error("ciphertext of another key accepted")
	}
	for _, bad := range []string{
		"", "hikyo:v", "hikyo:v0:AA", "hikyo:v01:AA", "hikyo:v-1:AA", "hikyo:v+1:AA",
		"hikyo:v4294967296:AA", "hikyo:v1:", "hikyo:v1:AA==", "hikyo:v1:A/+", "vault:v1:AA",
		"hikyo:v1:" + strings.Repeat("A", MaxTransitWireBytes),
	} {
		if _, _, err := ParseTransitValue(bad); err == nil {
			t.Errorf("ParseTransitValue(%.40q) accepted", bad)
		}
	}
}

func TestTransitMACCompare(t *testing.T) {
	k := mustTransitKey(t, TransitHMACSHA256)
	a, _ := k.MAC([]byte("m"))
	b, _ := k.MAC([]byte("m"))
	c, _ := k.MAC([]byte("n"))
	if !EqualTransitMAC(a, b) || EqualTransitMAC(a, c) || EqualTransitMAC(a, a[:5]) {
		t.Fatal("MAC comparison wrong")
	}
	if VerifyTransitSignature(TransitEd25519, make([]byte, 5), []byte("m"), make([]byte, 64)) {
		t.Fatal("short public key verified")
	}
}

func TestTransitKeyRedacts(t *testing.T) {
	k := mustTransitKey(t, TransitXChaCha20Poly1305)
	if k.String() != Redacted || k.GoString() != Redacted {
		t.Fatal("transit key does not redact")
	}
	k.Destroy()
	if !bytes.Equal(k.key, make([]byte, KeySize)) {
		t.Fatal("destroy did not zero the key")
	}
}

func TestTransitRandomnessFailureIsFatal(t *testing.T) {
	k := mustTransitKey(t, TransitXChaCha20Poly1305)
	k.rnd = bytes.NewReader(make([]byte, 10))
	if _, err := k.Encrypt([]byte("x"), nil); err == nil {
		t.Fatal("seal proceeded on a short randomness read")
	}
	if _, err := readRandom(bytes.NewReader(nil), 32); err == nil {
		t.Fatal("material generated from an empty reader")
	}
}

func TestTransitMLDSA65RefusesWrongAlgorithmUse(t *testing.T) {
	k := mustTransitKey(t, TransitMLDSA65)
	if _, err := k.Encrypt([]byte("x"), nil); err == nil {
		t.Error("signing key encrypted")
	}
	if _, err := k.MAC([]byte("x")); err == nil {
		t.Error("signing key MACed")
	}
	if _, err := mustTransitKey(t, TransitXChaCha20Poly1305).Sign([]byte("x")); err == nil {
		t.Error("encryption key signed")
	}
	if _, err := mustTransitKey(t, TransitHMACSHA256).PublicKey(); err == nil {
		t.Error("hmac key exposed a public key")
	}
	if _, err := k.Sign(make([]byte, MaxTransitPlaintextBytes+1)); !errors.Is(err, ErrTransitFormat) {
		t.Errorf("oversized message signed: %v", err)
	}
	if _, err := k.Sign(make([]byte, MaxTransitPlaintextBytes)); err != nil {
		t.Errorf("message at the bound refused: %v", err)
	}
}

// One material and one binding yield unrelated keys per algorithm: the
// algorithm is part of the HKDF info, so an ed25519 key and an mldsa65 key
// never share a seed (distinct key identities, DEC-02).
func TestTransitMLDSA65SeedIsAlgorithmBound(t *testing.T) {
	ed, err := mustTransitKey(t, TransitEd25519).PublicKey()
	if err != nil {
		t.Fatal(err)
	}
	pq, err := mustTransitKey(t, TransitMLDSA65).PublicKey()
	if err != nil {
		t.Fatal(err)
	}
	if len(ed) != 32 || len(pq) != 1952 || bytes.Equal(ed, pq[:32]) {
		t.Fatalf("public key sizes %d / %d or shared prefix", len(ed), len(pq))
	}
	other := goldenBinding(TransitMLDSA65)
	other.Version = 4
	k2, err := OpenTransitKey(goldenMaterial(), other)
	if err != nil {
		t.Fatal(err)
	}
	pq2, _ := k2.PublicKey()
	if bytes.Equal(pq, pq2) {
		t.Error("two versions over one material share a public key")
	}
}

// Every malformed key or payload is a plain false: wrong sizes, wrong
// identifier, unknown algorithm, a public key the library rejects, cross
// algorithm use, oversized message.
func TestTransitVerifyRefusesMalformedInputs(t *testing.T) {
	k := mustTransitKey(t, TransitMLDSA65)
	pub, _ := k.PublicKey()
	msg := []byte("m")
	payload, err := k.Sign(msg)
	if err != nil {
		t.Fatal(err)
	}
	if !VerifyTransitSignature(TransitMLDSA65, pub, msg, payload) {
		t.Fatal("genuine signature refused")
	}
	flip := func(b []byte, i int) []byte { c := bytes.Clone(b); c[i] ^= 1; return c }
	cases := map[string]struct {
		alg          TransitAlgorithm
		pub, payload []byte
		msg          []byte
	}{
		"empty payload":              {TransitMLDSA65, pub, nil, msg},
		"identifier only":            {TransitMLDSA65, pub, payload[:2], msg},
		"truncated by one":           {TransitMLDSA65, pub, payload[:len(payload)-1], msg},
		"extended by one":            {TransitMLDSA65, pub, append(bytes.Clone(payload), 0), msg},
		"signature without id":       {TransitMLDSA65, pub, payload[2:], msg},
		"wrong identifier high byte": {TransitMLDSA65, pub, flip(payload, 0), msg},
		"wrong identifier low byte":  {TransitMLDSA65, pub, flip(payload, 1), msg},
		"ml-dsa-44 identifier":       {TransitMLDSA65, pub, append([]byte{0x09, 0x04}, payload[2:]...), msg},
		"ml-dsa-87 identifier":       {TransitMLDSA65, pub, append([]byte{0x09, 0x06}, payload[2:]...), msg},
		"flipped signature byte":     {TransitMLDSA65, pub, flip(payload, 100), msg},
		"empty public key":           {TransitMLDSA65, nil, payload, msg},
		"short public key":           {TransitMLDSA65, pub[:1951], payload, msg},
		"long public key":            {TransitMLDSA65, append(bytes.Clone(pub), 0), payload, msg},
		"ed25519 sized public key":   {TransitMLDSA65, pub[:32], payload, msg},
		"flipped public key byte":    {TransitMLDSA65, flip(pub, 7), payload, msg},
		"all-zero public key":        {TransitMLDSA65, make([]byte, 1952), payload, msg},
		"oversized message":          {TransitMLDSA65, pub, payload, make([]byte, MaxTransitPlaintextBytes+1)},
		"unknown algorithm":          {TransitAlgorithm("mldsa87"), pub, payload, msg},
		"hmac algorithm":             {TransitHMACSHA256, pub, payload, msg},
		"empty algorithm":            {"", pub, payload, msg},
		"ed25519 verifier":           {TransitEd25519, pub[:32], payload, msg},
		"ed25519 verifier, full pub": {TransitEd25519, pub, payload, msg},
	}
	for name, c := range cases {
		if VerifyTransitSignature(c.alg, c.pub, c.msg, c.payload) {
			t.Errorf("%s: accepted", name)
		}
	}
	// And an Ed25519 signature never verifies under ML-DSA.
	edSig, _ := mustTransitKey(t, TransitEd25519).Sign(msg)
	if VerifyTransitSignature(TransitMLDSA65, pub, msg, edSig) {
		t.Error("ed25519 signature verified under ml-dsa")
	}
}

func TestTransitMLDSA65DestroyDropsTheKey(t *testing.T) {
	k := mustTransitKey(t, TransitMLDSA65)
	k.Destroy()
	if _, err := k.Sign([]byte("m")); err == nil {
		t.Error("destroyed ml-dsa key signed")
	}
	if _, err := k.PublicKey(); err == nil {
		t.Error("destroyed ml-dsa key returned a public key")
	}
	(*TransitKey)(nil).Destroy()
}

func TestTransitAlgorithmSetIsClosed(t *testing.T) {
	for _, a := range TransitAlgorithms() {
		if got, err := ParseTransitAlgorithm(string(a)); err != nil || got != a {
			t.Errorf("%s: %v", a, err)
		}
	}
	for _, bad := range []string{"", "mldsa44", "mldsa87", "ml-dsa-65", "MLDSA65", "mldsa65 ", "slh-dsa"} {
		if _, err := ParseTransitAlgorithm(bad); err == nil {
			t.Errorf("%q accepted", bad)
		}
	}
	if len(TransitMLDSASignContext) > 255 {
		t.Error("context exceeds the ML-DSA bound")
	}
}
